using ProjetoIntegradorBack.Api.Queries; using ProjetoIntegradorBack.Domain.DTOs; using ProjetoIntegradorBack.Domain.Interfaces; using Prime.Architecture.Mapper.Interfaces; using Prime.Architecture.Mediator.Standard.Requests;
namespace ProjetoIntegradorBack.Api.Handlers.NavalhaCorte;
public class ListarEstabelecimentosHandler(IEstabelecimentoRepository r,IMapper m):IRequestHandler<ListarEstabelecimentosQuery,PagedResultDto<EstabelecimentoDto>> { public async Task<PagedResultDto<EstabelecimentoDto>> Handle(ListarEstabelecimentosQuery q,CancellationToken ct){var x=await r.ListarAsync(q.Busca,q.Cidade,q.Pagina,q.Tamanho,ct);var t=await r.ContarAsync(q.Busca,q.Cidade,ct);return new(){Dados=x.IsSuccess?x.Success!.Select(e=>m.Map<Domain.Entities.Estabelecimento,EstabelecimentoDto>(e)).ToList():[],Pagina=q.Pagina,TamanhoPagina=q.Tamanho,Total=t.IsSuccess?t.Success:0};}}
public class ObterEstabelecimentoHandler(IEstabelecimentoRepository r,IMapper m):IRequestHandler<ObterEstabelecimentoQuery,EstabelecimentoDetalheDto>{public async Task<EstabelecimentoDetalheDto> Handle(ObterEstabelecimentoQuery q,CancellationToken ct){var x=await r.ObterPorIdAsync(q.Id,ct);if(x.IsFailure)throw new KeyNotFoundException();return m.Map<Domain.Entities.Estabelecimento,EstabelecimentoDetalheDto>(x.Success!);}}
